"""Every generated file: path → Dart source. Formatting is left to `dart format`."""
from __future__ import annotations

import re

import pycountry

from .dart import (
    access, dart_json, dart_type, display, enum_class, field_def, from_json, lower_first, nullable, q, sample, snake, to_json,
)
from .spec import ROOT, Entity, Screen, Spec, SpecError, resolve

HEAD = "// GENERATED by apps/app-v2/gen from apps/app-v2/spec. Do not edit: change the spec and run `python3 -m gen`.\n"

ICONS = {"home": "Icons.home_outlined", "inbox": "Icons.inbox_outlined", "orders": "Icons.receipt_long_outlined", "more": "Icons.menu"}
TONE = {"neutral": "Tone.neutral", "info": "Tone.info", "ok": "Tone.ok", "warn": "Tone.warn", "bad": "Tone.bad"}

WEB_THEME = ROOT.parent.parent / "packages/ui/src/styles/theme.css"
# Web token → Dart name. The web's theme.css is the one source of the colours.
COLOURS = [
    "bg", "surface", "surface-2", "surface-3", "line", "line-strong", "text", "text-2", "muted",
    "primary", "primary-hover", "primary-soft", "primary-fg", "primary-solid", "bad-solid",
    "trust", "trust-soft", "money", "money-soft", "ok", "ok-soft", "warn", "warn-soft", "bad", "bad-soft", "info", "info-soft",
    "chart-1", "chart-2", "chart-3", "chart-4", "chart-5",
]


def camel(token: str) -> str:
    head, *rest = token.split("-")
    return head + "".join(p[:1].upper() + p[1:] for p in rest)


def screen_class(s: Screen) -> str:
    return {"list": f"{s.name}Screen", "record": f"{s.name}Screen", "sheet": f"{s.name}Sheet"}[s.frame]


def screen_file(s: Screen) -> str:
    return f"lib/generated/screens/{snake(s.name)}.g.dart"


# ---------------------------------------------------------------- theme from the web


def tokens() -> str:
    css = WEB_THEME.read_text()

    def block(selector: str) -> dict[str, str]:
        m = re.search(re.escape(selector) + r"\s*\{(.*?)\n\}", css, re.S)
        if not m:
            raise SpecError(f"{WEB_THEME}: no '{selector}' block")
        return dict(re.findall(r"--([a-z0-9-]+):\s*(#[0-9a-fA-F]{6})\s*;", m.group(1)))

    light, dark = block(":root"), block(".dark")

    def colour(vals: dict[str, str], t: str) -> str:
        if t not in vals:
            raise SpecError(f"theme.css has no --{t}")
        return f"Color(0xFF{vals[t][1:].upper()})"

    fields = "\n".join(f"  final Color {camel(t)};" for t in COLOURS)
    ctor = ", ".join(f"required this.{camel(t)}" for t in COLOURS)
    light_v = ", ".join(f"{camel(t)}: {colour(light, t)}" for t in COLOURS)
    dark_v = ", ".join(f"{camel(t)}: {colour(dark, t)}" for t in COLOURS)
    copy_args = ", ".join(f"{camel(t)}: {camel(t)}" for t in COLOURS)
    lerp_args = ", ".join(f"{camel(t)}: Color.lerp({camel(t)}, o.{camel(t)}, t)!" for t in COLOURS)
    return f"""{HEAD}// Colours read from packages/ui/src/styles/theme.css, so the phone matches the web.
import 'package:flutter/material.dart';

@immutable
class AppColors extends ThemeExtension<AppColors> {{
  const AppColors({{{ctor}}});

{fields}

  static const light = AppColors({light_v});
  static const dark = AppColors({dark_v});

  @override
  AppColors copyWith() => AppColors({copy_args});

  @override
  AppColors lerp(ThemeExtension<AppColors>? other, double t) {{
    if (other is! AppColors) return this;
    final o = other;
    return AppColors({lerp_args});
  }}
}}
"""


def countries() -> str:
    rows = sorted((c.alpha_2, getattr(c, "common_name", None) or c.name) for c in pycountry.countries)
    body = ",\n".join(f"  {q(code)}: {q(name)}" for code, name in rows)
    return f"""{HEAD}/// ISO country codes and their names, A–Z by code.
const countries = <String, String>{{
{body},
}};

/// "PK" → "Pakistan"; an unknown code is shown as it is.
String? countryName(String? code) => code == null || code.isEmpty ? null : countries[code] ?? code;
"""


# ---------------------------------------------------------------- enums, models, fields, repos


def enums(spec: Spec) -> str:
    out = [HEAD, "import '../ds/tone.dart';\n"]
    for name, values in spec.enums.items():
        labels = ", ".join(f"{q(v)}: {q(m['label'])}" for v, m in values.items())
        tones = ", ".join(f"{q(v)}: {TONE[m['tone']]}" for v, m in values.items())
        out.append(f"""
abstract final class {enum_class(name)} {{
  static const values = <String>[{', '.join(q(v) for v in values)}];
  static const labels = <String, String>{{{labels}}};
  static const tones = <String, Tone>{{{tones}}};
  static String? label(String? v) => v == null ? null : labels[v] ?? v;
  static Badge? badge(String? v) => v == null ? null : Badge(labels[v] ?? v, tones[v] ?? Tone.neutral);
}}
""")
    return "".join(out)


def model(spec: Spec, e: Entity) -> str:
    fs = list(e.fields.values())
    finals = "\n".join(f"  final {dart_type(f)} {f.name};" for f in fs)

    def ctor_arg(f):
        if nullable(f):
            return f"this.{f.name}"
        default = {"list": "const []", "int": "0", "bool": "false"}.get(f.kind)
        if default is None:
            default = q(str(f.default)) if f.default is not None else "''"
        return f"this.{f.name} = {default}"

    ctor = ", ".join(ctor_arg(f) for f in fs)
    reads = ",\n".join(f"        {f.name}: {from_json(f)}" for f in fs)
    writes = []
    for f in fs:
        v = to_json(f)
        if v is None:
            continue
        if f.kind == "id":
            writes.append(f"        if ({f.name}.isNotEmpty) {q(f.name)}: {f.name}")
        else:
            writes.append(f"        {q(f.name)}: {v}")
    return f"""
class {e.name} {{
  const {e.name}({{{ctor}}});

{finals}

  factory {e.name}.fromJson(Json j) => {e.name}(
{reads},
      );

  Json toJson() => {{
{','.join(chr(10) + w for w in writes)}
      }};
}}
"""


def fields_class(spec: Spec, e: Entity) -> str:
    editable = [f for f in e.fields.values() if not f.readonly and f.kind not in ("obj", "list")]
    defs = "\n".join(f"  static const {f.name} = {field_def(spec, e, f)};" for f in editable)
    rules = ", ".join(
        f"AnyOf([{', '.join(q(k) for k in r['any'])}], {q(r['message'])})" for r in e.rules if r.get("any")
    )
    blank = []
    for f in e.fields.values():
        if f.readonly or f.kind == "obj":
            continue
        if f.kind == "list":
            item = f"[{f.ref}Fields.blank()]" if (f.min or 0) >= 1 else "[]"
            blank.append(f"{q(f.name)}: <Json>{item}")
        elif f.kind == "bool":
            blank.append(f"{q(f.name)}: false")
        elif f.default is not None:
            blank.append(f"{q(f.name)}: {q(str(f.default))}")
    return f"""
abstract final class {e.name}Fields {{
{defs}
  static const rules = <AnyOf>[{rules}];

  /// A new, empty {e.name} as a form starts it.
  static Json blank() => {{{', '.join(blank)}}};
}}
"""


def models(spec: Spec) -> str:
    body = "".join(model(spec, e) + fields_class(spec, e) for e in spec.entities.values())
    return f"""{HEAD}import '../core/json.dart';
import '../ds/fields.dart';
import 'enums.g.dart';

{body}"""


def repos(spec: Spec) -> str:
    out = [HEAD, "import '../core/api.dart';\nimport '../core/json.dart';\nimport 'models.g.dart';\n"]
    for e in spec.entities.values():
        if not e.api:
            continue
        api, n = e.api, e.name
        lst = (
            f"""  Future<Paged<{n}>> list({{String? q, int page = 1, Map<String, Object?> filters = const {{}}}}) async =>
      Paged.fromJson(await api.get({q(api)}, query: {{'q': q, 'page': page, 'pageSize': 25, ...filters}}), {n}.fromJson);"""
            if e.paged
            else f"""  Future<Paged<{n}>> list({{String? q, int page = 1, Map<String, Object?> filters = const {{}}}}) async =>
      Paged.all((await api.getList({q(api)}, query: {{'q': q, ...filters}})).map({n}.fromJson).toList());"""
        )
        out.append(f"""
class {n}Repo {{
  const {n}Repo(this.api);
  final Api api;

{lst}
  Future<{n}> get(String id) async => {n}.fromJson(await api.get('{api}/$id'));
  Future<{n}> create(Json body) async => {n}.fromJson(await api.post({q(api)}, body));
  Future<{n}> update(String id, Json body) async => {n}.fromJson(await api.put('{api}/$id', body));
  Future<void> delete(String id) => api.delete('{api}/$id');
}}
""")
    return "".join(out)


# ---------------------------------------------------------------- screens


def _row(spec: Spec, entity: str, row: dict, var: str, actions: list[str] | None = None, tap: str | None = None) -> str:
    args = [f"title: {display(spec, entity, row['title'], var)}"]
    if row.get("sub"):
        args.append(f"sub: [{', '.join(display(spec, entity, s, var) for s in row['sub'])}]")
    if row.get("badge"):
        f = resolve(spec, entity, row["badge"], entity)[-1]
        args.append(f"badge: {enum_class(f.ref)}.badge({access(resolve(spec, entity, row['badge'], entity), var)})")
    if row.get("value"):
        args.append(f"value: {display(spec, entity, row['value'], var)}")
    if actions:
        acts = ", ".join(f"ContactAction.{a}({var}.{a})" for a in actions)
        args.append(f"actions: [{acts}]")
    if tap:
        args.append(f"onTap: {tap}")
    return f"RowData({', '.join(args)})"


def _imports(spec: Spec, s: Screen, extra: set[str]) -> str:
    lines = [
        "import 'package:flutter/material.dart';",
        "import '../../core/scope.dart';",
        "import '../../ds/ds.dart';",
        "import '../countries.g.dart';",
        "import '../enums.g.dart';",
        "import '../models.g.dart';",
        "import '../repos.g.dart';",
    ]
    for name in sorted(extra):
        lines.append(f"import '{snake(name)}.g.dart';")
    return HEAD + "// ignore_for_file: unused_import\n" + "\n".join(lines) + "\n"


def list_screen(spec: Spec, s: Screen) -> str:
    r, e = s.raw, spec.entities[s.entity]
    extra: set[str] = set()
    args = [
        f"title: {q(r.get('title', s.name))}",
        f"load: (api, q, page) => {e.name}Repo(api).list(q: q, page: page)",
        f"row: (x) => {_row(spec, e.name, r['row'], 'x')}",
    ]
    if r.get("search"):
        args.append(f"searchHint: {q(r['search'])}")
    if r.get("open"):
        target = spec.screens[r["open"]]
        path = target.raw["path"].replace(":id", "${x.id}")
        args.append(f"onOpen: (context, x) => openPage(context, '{path}')")
    if r.get("add"):
        sheet = spec.screens[r["add"]]
        extra.add(sheet.name)
        title = (sheet.raw.get("title") or {}).get("create", "Add")
        perm = e.permissions.get("create")
        args.append(f"add: AddAction(label: {q(title)}, perm: {q(perm) if perm else 'null'}, open: {screen_class(sheet)}.create)")
    return f"""{_imports(spec, s, extra)}
class {screen_class(s)} extends StatelessWidget {{
  const {screen_class(s)}({{super.key}});

  @override
  Widget build(BuildContext context) => ListFrame<{e.name}>(
        {(',' + chr(10) + '        ').join(args)},
      );
}}
"""


def record_screen(spec: Spec, s: Screen) -> str:
    r, e = s.raw, spec.entities[s.entity]
    extra: set[str] = set()
    h = r.get("header") or {}
    args = [
        f"load: (api) => {e.name}Repo(api).get(id)",
        f"title: (x) => {display(spec, e.name, h['title'], 'x')}",
    ]
    if h.get("sub"):
        args.append(f"sub: (x) => [{', '.join(display(spec, e.name, it, 'x') for it in h['sub'])}]")

    def action(a: dict) -> str:
        perm = q(a["perm"]) if a.get("perm") else "null"
        if a.get("delete"):
            confirm = q(a.get("confirm", "Delete this?"))
            return f"RecordAction.delete(label: {q(a['label'])}, perm: {perm}, confirm: {confirm}, run: (api, x) => {e.name}Repo(api).delete(x.id))"
        if a.get("sheet"):
            sheet = spec.screens[a["sheet"]]
            extra.add(sheet.name)
            return f"RecordAction(label: {q(a['label'])}, perm: {perm}, run: {screen_class(sheet)}.edit)"
        raise SpecError(f"{s.source}: {s.name}: an action needs 'sheet' or 'delete'")

    if r.get("primary"):
        args.append(f"primary: {action(r['primary'])}")
    if r.get("more"):
        args.append(f"more: [{', '.join(action(a) for a in r['more'])}]")
    secs = []
    for sec in r.get("sections") or []:
        title = q(sec["title"])
        if "fields" in sec:
            pairs = ", ".join(f"({q(resolve(spec, e.name, p, e.name)[-1].label)}, {display(spec, e.name, p, 'x')})" for p in sec["fields"])
            secs.append(f"KvSection({title}, [{pairs}])")
        else:
            chain = resolve(spec, e.name, sec["list"], e.name)
            item = chain[-1].ref
            row = _row(spec, item, sec["row"], "y", sec.get("actions"))
            empty = f", empty: {q(sec['empty'])}" if sec.get("empty") else ""
            secs.append(f"ListSection({title}, [for (final y in {access(chain, 'x')}) {row}]{empty})")
    args.append(f"sections: (x) => [{', '.join(secs)}]")
    return f"""{_imports(spec, s, extra)}
class {screen_class(s)} extends StatelessWidget {{
  const {screen_class(s)}({{super.key, required this.id}});
  final String id;

  @override
  Widget build(BuildContext context) => RecordFrame<{e.name}>(
        {(',' + chr(10) + '        ').join(args)},
      );
}}
"""


def sheet_screen(spec: Spec, s: Screen) -> str:
    r, e = s.raw, spec.entities[s.entity]
    groups = []
    for g in r.get("groups") or []:
        ga = []
        if g.get("title"):
            ga.append(f"title: {q(g['title'])}")
        if g.get("folded"):
            ga.append("folded: true")
        if g.get("list"):
            lf = resolve(spec, e.name, g["list"], e.name)[-1]
            sub = spec.entities[lf.ref]
            fl = ", ".join(f"{sub.name}Fields.{f}" for f in g["fields"])
            add = q(g.get("add", "Add"))
            ga.append(
                f"list: ListDef({q(lf.name)}, itemLabel: {q(sub.name)}, addLabel: {add}, min: {lf.min or 0}, "
                f"fields: [{fl}], rules: {sub.name}Fields.rules, blank: {sub.name}Fields.blank)"
            )
        else:
            ga.append(f"fields: [{', '.join(f'{e.name}Fields.{f}' for f in g['fields'])}]")
        groups.append(f"FormGroup({', '.join(ga)})")
    titles = r.get("title") or {}
    dup = q(e.duplicate_flag) if e.duplicate_flag else "null"
    common = f"save: {q(r['save'])}, groups: _groups, rules: {e.name}Fields.rules, duplicateFlag: {dup}"
    return f"""{_imports(spec, s, set())}
abstract final class {screen_class(s)} {{
  static const _groups = <FormGroup>[{', '.join(groups)}];

  /// Opens the empty form; true when something was saved.
  static Future<bool> create(BuildContext context) => FormSheet.open(
        context,
        title: {q(titles.get('create', 'New ' + e.name.lower()))},
        initial: {e.name}Fields.blank(),
        send: (api, body) => {e.name}Repo(api).create(body),
        {common},
      );

  /// Opens the form filled from [x]; true when the change was saved.
  static Future<bool> edit(BuildContext context, {e.name} x) => FormSheet.open(
        context,
        title: {q(titles.get('edit', 'Edit ' + e.name.lower()))},
        initial: x.toJson(),
        send: (api, body) => {e.name}Repo(api).update(x.id, body),
        {common},
      );
}}
"""


def routes(spec: Spec) -> str:
    tabs = spec.app.get("tabs") or []
    tab_index = {t["label"]: i for i, t in enumerate(tabs)}
    imports, gr, owners = [], [], {}
    for s in spec.screens.values():
        if s.frame == "sheet":
            continue
        imports.append(f"import 'screens/{snake(s.name)}.g.dart';")
        path = s.raw["path"]
        build = f"const {screen_class(s)}()" if s.frame == "list" else f"{screen_class(s)}(id: s.pathParameters['id']!)"
        gr.append(f"  GoRoute(path: {q(path)}, builder: (c, s) => {build}),")
        tab = s.raw.get("tab", "More")
        if tab not in tab_index:
            raise SpecError(f"{s.source}: {s.name}: tab '{tab}' is not in app.yaml")
        owners[path.split('/:')[0]] = tab_index[tab]
    tab_defs = "\n".join(f"  TabDef({q(t['label'])}, {ICONS[t['icon']]}, {q(t['path'])})," for t in tabs)
    return f"""{HEAD}import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';
import '../ds/tab_def.dart';
{chr(10).join(sorted(set(imports)))}

const appName = {q(spec.app['app'])};

const appTabs = <TabDef>[
{tab_defs}
];

/// Which tab is lit for a generated screen's path.
const routeTabs = <String, int>{{
{chr(10).join(f"  {q(k)}: {v}," for k, v in owners.items())}
}};

final generatedRoutes = <RouteBase>[
{chr(10).join(gr)}
];
"""


# ---------------------------------------------------------------- tests


def tests(spec: Spec) -> str:
    cases = []
    for e in spec.entities.values():
        j = sample(spec, e.name)
        cases.append(f"""
  test({q(e.name + ' reads and writes its JSON')}, () {{
    final j = jsonDecode({dart_json(j)}) as Json;
    final x = {e.name}.fromJson(j);
    final back = x.toJson();
    for (final k in back.keys) {{
      if (j[k] is! List && j[k] is! Map) expect(back[k], j[k], reason: k);
    }}
  }});""")
    for s in spec.screens.values():
        e = spec.entities[s.entity]
        j = sample(spec, e.name)
        if s.frame == "list":
            title_field = resolve(spec, e.name, s.raw["row"]["title"], e.name)
            title = j
            for f in title_field:
                title = title[f.name]
            body = {"total": 1, "page": 1, "pageSize": 25, "rows": [j]} if e.paged else [j]
            cases.append(f"""
  testWidgets({q(s.name + ' lists the rows and passes the accessibility checks')}, (tester) async {{
    await pumpScreen(tester, const {screen_class(s)}(), {{{q(e.api)}: jsonDecode({dart_json(body)})}});
    expect(find.text({q(s.raw.get('title', s.name))}), findsWidgets);
    expect(find.text({q(str(title))}), findsOneWidget);
    await expectAccessible(tester);
  }});""")
        elif s.frame == "record":
            title = j
            for f in resolve(spec, e.name, s.raw["header"]["title"], e.name):
                title = title[f.name]
            sections = [sec["title"] for sec in s.raw.get("sections") or []]
            cases.append(f"""
  testWidgets({q(s.name + ' shows the record and passes the accessibility checks')}, (tester) async {{
    await pumpScreen(tester, const {screen_class(s)}(id: {q(j['id'])}), {{'{e.api}/{j['id']}': jsonDecode({dart_json(j)})}});
    expect(find.text({q(str(title))}), findsWidgets);
    for (final t in <String>[{', '.join(q(x) for x in sections)}]) {{
      final section = find.byKey(ValueKey('section:$t'));
      await tester.scrollUntilVisible(section, 200, scrollable: find.byType(Scrollable).first);
      expect(section, findsOneWidget);
    }}
    await expectAccessible(tester);
  }});""")
        elif s.frame == "sheet":
            required = []
            for g in s.raw.get("groups") or []:
                if not g.get("list") and not g.get("folded"):
                    required += [e.fields[f].label for f in g["fields"] if e.fields[f].required and e.fields[f].default is None]
            checks = "\n".join(f"    expect(find.text({q(lbl + ' is needed')}), findsWidgets);" for lbl in required)
            cases.append(f"""
  testWidgets({q(s.name + ' checks required fields before sending')}, (tester) async {{
    await pumpSheet(tester, (context) => {screen_class(s)}.create(context));
    await tester.tap(find.text({q(s.raw['save'])}));
    await tester.pumpAndSettle();
{checks}
    await expectAccessible(tester);
  }});""")
    imports = sorted({f"import 'package:kebo_app/generated/screens/{snake(s.name)}.g.dart';" for s in spec.screens.values()})
    return f"""{HEAD}import 'dart:convert';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:kebo_app/core/json.dart';
import 'package:kebo_app/generated/models.g.dart';
{chr(10).join(imports)}

import '../support/harness.dart';

void main() {{{''.join(cases)}
}}
"""


def all_files(spec: Spec) -> dict[str, str]:
    files = {
        "lib/ds/tokens.g.dart": tokens(),
        "lib/generated/countries.g.dart": countries(),
        "lib/generated/enums.g.dart": enums(spec),
        "lib/generated/models.g.dart": models(spec),
        "lib/generated/repos.g.dart": repos(spec),
        "lib/generated/routes.g.dart": routes(spec),
        "test/generated/generated_test.dart": tests(spec),
    }
    for s in spec.screens.values():
        files[screen_file(s)] = {"list": list_screen, "record": record_screen, "sheet": sheet_screen}[s.frame](spec, s)
    return files
